def compute(vars):
    finished_goods = vars["v1"]
    total_inventories = vars["v2"]

    if total_inventories == 0:
        return None

    proportion = finished_goods / total_inventories

    return {
        "value": proportion,
        "trace": {
            "finished_goods": finished_goods,
            "total_inventories": total_inventories,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "proportion"
            }
        }
    }
